CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE IF NOT EXISTS tenants(id text PRIMARY KEY, name text NOT NULL, slug text UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS professionals(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants, name text NOT NULL, specialty text NOT NULL, color text NOT NULL, commission_bps integer NOT NULL CHECK(commission_bps BETWEEN 0 AND 10000), UNIQUE(id,tenant_id));
CREATE TABLE IF NOT EXISTS services(id text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants, name text NOT NULL, description text NOT NULL, price integer NOT NULL CHECK(price>=0), duration integer NOT NULL CHECK(duration>0), UNIQUE(id,tenant_id));
CREATE TABLE IF NOT EXISTS appointments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id text NOT NULL REFERENCES tenants, professional_id text NOT NULL, service_id text NOT NULL, customer text NOT NULL, phone text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, price integer NOT NULL CHECK(price>=0), commission_bps integer NOT NULL, commission integer NOT NULL CHECK(commission>=0), status text NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','confirmed','in_progress','completed','cancelled','no_show')), paid integer NOT NULL DEFAULT 0 CHECK(paid>=0 AND paid<=price), payment_method text CHECK(payment_method IN ('Pix','Dinheiro','Cartão')), consent boolean NOT NULL DEFAULT false, manage_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(professional_id,tenant_id) REFERENCES professionals(id,tenant_id), FOREIGN KEY(service_id,tenant_id) REFERENCES services(id,tenant_id), CHECK(ends_at>starts_at), CONSTRAINT no_overlap EXCLUDE USING gist (professional_id WITH =, tstzrange(starts_at,ends_at,'[)') WITH &&) WHERE (status IN ('scheduled','confirmed','in_progress','completed')));
CREATE TABLE IF NOT EXISTS expenses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id text NOT NULL REFERENCES tenants, description text NOT NULL, amount integer NOT NULL CHECK(amount>0), paid_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payouts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id text NOT NULL REFERENCES tenants, professional_id text NOT NULL, amount integer NOT NULL CHECK(amount>0), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(professional_id,tenant_id) REFERENCES professionals(id,tenant_id));
CREATE TABLE IF NOT EXISTS notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), appointment_id uuid NOT NULL REFERENCES appointments, kind text NOT NULL, due_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, delivered_at timestamptz, UNIQUE(appointment_id,kind));
CREATE TABLE IF NOT EXISTS audit_log(id bigserial PRIMARY KEY, tenant_id text NOT NULL, action text NOT NULL, entity_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY, tenant_id text NOT NULL REFERENCES tenants, role text NOT NULL, professional_id text, expires_at timestamptz NOT NULL);
